import { put } from "@vercel/blob";
import fallbackPayload from "@/data/ai-activity.fallback.json";
import {
  AI_ACTIVITY_BLOB_PATH,
  type AiActivityPayload,
  parseAiActivityPayload,
} from "@/lib/ai-activity-payload";
import type { AiActivitySource } from "@/lib/ai-activity";

export async function publishAiActivityPayload(
  payload: AiActivityPayload,
): Promise<{ url: string }> {
  const token = process.env.BLOB_READ_WRITE_TOKEN;
  if (!token) {
    throw new Error("BLOB_READ_WRITE_TOKEN is not configured");
  }

  const blob = await put(AI_ACTIVITY_BLOB_PATH, JSON.stringify(payload), {
    access: "public",
    addRandomSuffix: false,
    allowOverwrite: true,
    contentType: "application/json",
    token,
    cacheControlMaxAge: 3600,
  });

  return { url: blob.url };
}

function payloadFromFallback(): AiActivityPayload {
  const parsed = parseAiActivityPayload(fallbackPayload);
  if (!parsed) {
    throw new Error(
      "data/ai-activity.fallback.json is missing or invalid — fix the seed file",
    );
  }
  return parsed;
}

export async function fetchPublishedAiActivityPayload(): Promise<AiActivityPayload | null> {
  const url = process.env.AI_ACTIVITY_BLOB_URL;
  if (!url) return null;

  try {
    const res = await fetch(url, {
      next: { revalidate: 3600 },
    });
    if (!res.ok) {
      console.warn(`[ai-activity] blob fetch HTTP ${res.status} for ${url}`);
      return null;
    }
    const json: unknown = await res.json();
    const parsed = parseAiActivityPayload(json);
    if (!parsed) {
      console.warn("[ai-activity] blob payload failed validation");
      return null;
    }
    return parsed;
  } catch (error) {
    console.warn("[ai-activity] blob fetch failed", error);
    return null;
  }
}

/**
 * Load published (or fallback) history. Today’s live projection is applied
 * client-side so ISR cache does not freeze the day-fraction.
 */
export async function getAiActivityPayload(): Promise<{
  payload: AiActivityPayload;
  source: AiActivitySource;
}> {
  const published = await fetchPublishedAiActivityPayload();
  if (published) return { payload: published, source: "blob" };
  return { payload: payloadFromFallback(), source: "fallback" };
}
/**
 * Keyboard / focus chrome contracts for the Editorial shell.
 * Used by Primary nav, theme control, and outbound Project/Post links.
 */
export const FOCUSABLE_CHROME = {
  primaryNavLabel: "Primary",
  skipToContentHref: "#main-content",
  skipToContentLabel: "Skip to content",
  mainContentId: "main-content",
} as const;

/** A control is keyboard-reachable when it can receive focus and has a name. */
export function isKeyboardReachableControl(options: {
  hasAccessibleName: boolean;
  tabbable: boolean;
}): boolean {
  return options.tabbable && options.hasAccessibleName;
}
import fs from "node:fs";
import path from "node:path";

export type PostFrontmatter = {
  title: string;
  publishedAt: string;
  summary: string;
  tags?: string[];
  draft?: boolean;
  image?: string;
};

export type PostRecord = PostFrontmatter & {
  slug: string;
  content: string;
  readingTimeMinutes: number;
};

const POSTS_DIR = path.join(process.cwd(), "content", "blog");

/** ~200 wpm; minimum 1 minute when there is body text. */
export function estimateReadingTimeMinutes(content: string): number {
  const words = content.trim().split(/\s+/).filter(Boolean).length;
  if (words === 0) return 1;
  return Math.max(1, Math.ceil(words / 200));
}

function parseTags(raw: string | undefined): string[] | undefined {
  if (!raw) return undefined;
  const tags = raw
    .split(",")
    .map((t) => t.trim())
    .filter(Boolean);
  return tags.length > 0 ? tags : undefined;
}

function parseBool(raw: string | undefined): boolean {
  if (!raw) return false;
  return ["true", "yes", "on", "1"].includes(raw.toLowerCase());
}

function parseFrontmatterFields(
  slug: string,
  fileContent: string,
): { fields: Record<string, string>; content: string } {
  const frontmatterRegex = /^---\s*\n([\s\S]*?)\n---\s*/;
  const match = frontmatterRegex.exec(fileContent);
  if (!match) {
    throw new Error(`Post "${slug}" is missing frontmatter`);
  }

  const block = match[1] ?? "";
  const content = fileContent.slice(match[0].length).trim();
  const fields: Record<string, string> = {};

  for (const line of block.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const sep = trimmed.indexOf(":");
    if (sep === -1) continue;
    const key = trimmed.slice(0, sep).trim();
    let value = trimmed.slice(sep + 1).trim();
    // Single-line frontmatter only — reject YAML block scalars (>, |, >-, |-, etc.).
    if (value === ">" || value === "|" || value.startsWith(">") || value.startsWith("|")) {
      throw new Error(
        `Post "${slug}" field "${key}" uses unsupported YAML block syntax; use a single-line value`,
      );
    }
    value = value.replace(/^['"](.*)['"]$/, "$1");
    fields[key] = value;
  }

  return { fields, content };
}

/**
 * Parses a Post from MDX source. Incomplete drafts (missing required
 * frontmatter) return `null` so WIP files cannot break public builds.
 * Incomplete published Posts still throw.
 */
export function tryParsePostSource(
  slug: string,
  fileContent: string,
): PostRecord | null {
  let fields: Record<string, string>;
  let content: string;
  try {
    ({ fields, content } = parseFrontmatterFields(slug, fileContent));
  } catch (error) {
    // WIP drafts with unsupported YAML must not break Home / RSS / sitemap.
    if (/\bdraft:\s*(true|yes|on|1)\b/i.test(fileContent)) {
      return null;
    }
    throw error;
  }

  const title = fields.title;
  const publishedAt = fields.publishedAt;
  const summary = fields.summary;
  const draft = parseBool(fields.draft);

  if (!title || !publishedAt || !summary) {
    if (draft) return null;
    throw new Error(
      `Post "${slug}" requires title, publishedAt, and summary frontmatter`,
    );
  }

  return {
    slug,
    title,
    publishedAt,
    summary,
    tags: parseTags(fields.tags),
    draft,
    image: fields.image,
    content,
    readingTimeMinutes: estimateReadingTimeMinutes(content),
  };
}

export function parsePostSource(slug: string, fileContent: string): PostRecord {
  const post = tryParsePostSource(slug, fileContent);
  if (!post) {
    throw new Error(
      `Post "${slug}" is an incomplete draft (missing title, publishedAt, or summary)`,
    );
  }
  return post;
}

export function selectPublishedPosts(
  posts: readonly PostRecord[],
): PostRecord[] {
  return posts
    .filter((p) => !p.draft)
    .slice()
    .sort(
      (a, b) =>
        new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime(),
    );
}

export function selectLatestPublished(
  posts: readonly PostRecord[],
  limit: number,
): PostRecord[] {
  return selectPublishedPosts(posts).slice(0, limit);
}

function listMdxFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir).filter((file) => path.extname(file) === ".mdx");
}

/** All Posts from disk (including complete drafts; skips incomplete drafts). */
export function getAllPosts(): PostRecord[] {
  return listMdxFiles(POSTS_DIR).flatMap((file) => {
    const slug = path.basename(file, path.extname(file));
    const raw = fs.readFileSync(path.join(POSTS_DIR, file), "utf-8");
    const post = tryParsePostSource(slug, raw);
    return post ? [post] : [];
  });
}

export function getPublishedPosts(): PostRecord[] {
  return selectPublishedPosts(getAllPosts());
}

export function getPostBySlug(slug: string): PostRecord | undefined {
  const post = getAllPosts().find((p) => p.slug === slug);
  if (!post || post.draft) return undefined;
  return post;
}

export function getLatestPublishedPosts(limit = 3): PostRecord[] {
  return selectLatestPublished(getAllPosts(), limit);
}

export function formatPostDate(date: string): string {
  const value = date.includes("T") ? date : `${date}T00:00:00`;
  return new Date(value).toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  });
}
import type { PostRecord } from "./blog";

export type RssInput = {
  siteUrl: string;
  siteName: string;
  description: string;
  posts: readonly PostRecord[];
};

export type SitemapEntry = {
  url: string;
  lastModified: string;
};

function escapeXml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

export function buildRssXml({
  siteUrl,
  siteName,
  description,
  posts,
}: RssInput): string {
  const items = posts
    .slice()
    .sort(
      (a, b) =>
        new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime(),
    )
    .map(
      (post) => `    <item>
      <title>${escapeXml(post.title)}</title>
      <link>${escapeXml(`${siteUrl}/blog/${encodeURIComponent(post.slug)}`)}</link>
      <guid>${escapeXml(`${siteUrl}/blog/${encodeURIComponent(post.slug)}`)}</guid>
      <description>${escapeXml(post.summary)}</description>
      <pubDate>${new Date(post.publishedAt).toUTCString()}</pubDate>
    </item>`,
    )
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>${escapeXml(siteName)}</title>
    <link>${siteUrl}</link>
    <description>${escapeXml(description)}</description>
${items ? `${items}\n` : ""}  </channel>
</rss>`;
}

export function buildSitemapEntries({
  siteUrl,
  posts,
}: {
  siteUrl: string;
  posts: readonly PostRecord[];
}): SitemapEntry[] {
  const today = new Date().toISOString().slice(0, 10);
  const core = ["", "/blog", "/projects"].map((route) => ({
    url: `${siteUrl}${route}`,
    lastModified: today,
  }));

  const postEntries = posts.map((post) => ({
    url: `${siteUrl}/blog/${encodeURIComponent(post.slug)}`,
    lastModified: post.publishedAt,
  }));

  return [...core, ...postEntries];
}

export function ogImagePath(title: string): string {
  return `/og?title=${encodeURIComponent(title)}`;
}
export function cn(...classes: Array<string | undefined | false | null>) {
  return classes.filter(Boolean).join(" ");
}
export type SocialLink = {
  label: "X" | "GitHub" | "LinkedIn" | "Email";
