1	import { describe, expect, test } from "bun:test";
2	import { buildRssXml, buildSitemapEntries } from "./discovery";
3	import type { PostRecord } from "./blog";
4	
5	const samplePost: PostRecord = {
6	  slug: "judgment",
7	  title: "Product & judgment",
8	  publishedAt: "2026-06-01",
9	  summary: "Why judgment beats slogans.",
10	  draft: false,
11	  content: "Body",
12	  readingTimeMinutes: 1,
13	};
14	
15	describe("discovery contracts", () => {
16	  test("RSS includes only published Posts and stays valid when empty", () => {
17	    const empty = buildRssXml({
18	      siteUrl: "https://dhruv2mars.com",
19	      siteName: "Dhruv Sharma",
20	      description: "AI-pilled Design Engineer.",
21	      posts: [],
22	    });
23	    expect(empty).toContain("<rss");
24	    expect(empty).toContain("<channel>");
25	    expect(empty).not.toContain("<item>");
26	
27	    const withPost = buildRssXml({
28	      siteUrl: "https://dhruv2mars.com",
29	      siteName: "Dhruv Sharma",
30	      description: "AI-pilled Design Engineer.",
31	      posts: [samplePost],
32	    });
33	    expect(withPost).toContain("<item>");
34	    expect(withPost).toContain("https://dhruv2mars.com/blog/judgment");
35	    expect(withPost).toContain("Product &amp; judgment");
36	    expect(withPost).not.toContain("/writings/");
37	
38	    const ampersandSlug = buildRssXml({
39	      siteUrl: "https://dhruv2mars.com",
40	      siteName: "Dhruv Sharma",
41	      description: "AI-pilled Design Engineer.",
42	      posts: [{ ...samplePost, slug: "ai&design" }],
43	    });
44	    expect(ampersandSlug).toContain(
45	      "https://dhruv2mars.com/blog/ai%26design",
46	    );
47	    expect(ampersandSlug).not.toContain("/blog/ai&design");
48	  });
49	
