/**
 * Append the live today cell. Projection is ≤ recent positive days, so
 * existing intensities stay valid without a full rebuild.
 * Lifetime stays the published nightly total (excludes synthetic today).
 *
 * A stale payload (nightly sync down for a week, say) leaves a gap between
 * the last published day and today. Those days are zero-filled rather than
 * skipped: the series must stay consecutive or every cell in the grid lands
 * on the wrong weekday.
 */
export function withLiveToday(history: AiActivity, now = new Date()): AiActivity {
  const projection = projectTodayTokens(
    history.days,
    now,
    history.timezone,
  );
  const lastPublished = history.days.at(-1)?.date ?? "";
  // Avoid duplicating the last published day if clocks briefly disagree.
  if (projection.date <= lastPublished) {
    return history;
  }
  const max = Math.max(0, ...history.days.map((d) => d.tokens));

  const gap: ActivityDay[] = [];
  for (
    let cursor = lastPublished ? shiftYmd(lastPublished, 1) : projection.date;
    cursor < projection.date;
    cursor = shiftYmd(cursor, 1)
  ) {
    gap.push({ date: cursor, tokens: 0, intensity: 0 });
  }

  return {
    days: [
      ...history.days,
      ...gap,
      {
