  const lum = (c) => {
    const [r,g,b] = c.map(v => { v/=255; return v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4); });
    return 0.2126*r + 0.7152*g + 0.0722*b;
  };
  const parse = (s) => { const d = document.createElement('div'); d.style.color = s; document.body.appendChild(d); const c = getComputedStyle(d).color.match(/[\d.]+/g).slice(0,3).map(Number); d.remove(); return c; };
  const ratio = (a,b) => { const [x,y] = [lum(parse(a)), lum(parse(b))].sort((p,q)=>q-p); return +((x+0.05)/(y+0.05)).toFixed(2); };
  const cs = getComputedStyle(document.documentElement);
  const bg = cs.getPropertyValue('--background');
  const out = {};
  for (const t of ['--foreground','--muted','--dim','--accent']) out[t] = ratio(cs.getPropertyValue(t), bg);
  return { theme: document.documentElement.className.split(' ').pop(), contrast: out };
})()

(() => {
