  const ctx = cv.getContext('2d');
  const px = (s) => { ctx.clearRect(0,0,1,1); ctx.fillStyle = s; ctx.fillRect(0,0,1,1); return [...ctx.getImageData(0,0,1,1).data].slice(0,3); };
  const lum = (c) => { const [r,g,b] = c.map(v => { v/=255; return v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4); }); return 0.2126*r + 0.7152*g + 0.0722*b; };
  const ratio = (a,b) => { const [x,y] = [lum(px(a)), lum(px(b))].sort((p,q)=>q-p); return +((x+0.05)/(y+0.05)).toFixed(2); };
  const cs = getComputedStyle(document.documentElement);
  const bg = cs.getPropertyValue('--background');
  const out = { _bgRGB: px(bg) };
  for (const t of ['--foreground','--muted','--dim','--accent','--border']) out[t] = ratio(cs.getPropertyValue(t), bg);
  const nav = [...document.querySelectorAll('header a, header button')].map(e => { const r = e.getBoundingClientRect(); return [(e.textContent||e.getAttribute('aria-label')).trim().slice(0,14), Math.round(r.width), Math.round(r.height)]; });
