    f.style.cssText = `position:fixed;left:-9999px;top:0;border:0;width:${w}px;height:900px`;
    f.src = '/';
    document.body.appendChild(f);
    await new Promise(res => { f.onload = res; setTimeout(res, 6000); });
    await new Promise(r => setTimeout(r, 400));
    const d = f.contentDocument.documentElement;
    const cols = f.contentDocument.querySelectorAll('.activity-col:not([data-narrow-hidden]) ');
    out[w] = { overflow: d.scrollWidth - d.clientWidth, visibleWeeks: cols.length, cell: Math.round((f.contentDocument.querySelector('.activity-cell')?.getBoundingClientRect().width ?? 0) * 10) / 10 };
    f.remove();
  }
  return out;
})()

(async () => {
  const f = document.createElement('iframe');
  f.style.cssText = 'position:fixed;left:-9999px;top:0;border:0;width:390px;height:844px';
  f.src = '/';
  document.body.appendChild(f);
  await new Promise(res => { f.onload = res; setTimeout(res, 8000); });
  await new Promise(r => setTimeout(r, 1200));
  const doc = f.contentDocument, d = doc.documentElement;
  const cols = [...doc.querySelectorAll('.activity-col')];
  const shown = cols.filter(c => f.contentWindow.getComputedStyle(c).display !== 'none');
  const cell = shown.at(-1)?.querySelector('.activity-cell')?.getBoundingClientRect();
  const small = [...doc.querySelectorAll('header a, header button, footer a, main section:first-of-type a')]
    .map(e => { const r = e.getBoundingClientRect(); return [(e.textContent || e.getAttribute('aria-label')).trim().slice(0,12), Math.round(r.width), Math.round(r.height)]; })
    .filter(o => o[1] < 24 || o[2] < 24);
  const out = { overflow: d.scrollWidth - d.clientWidth, totalCols: cols.length, shownCols: shown.length, cellW: Math.round((cell?.width ?? 0) * 10) / 10, subMinTargets: small };
  f.remove();
  return out;
})()

