import Link from "next/link";
import { CommandPalette } from "@/components/command-palette";
import { ThemeToggle } from "@/components/theme-toggle";
import { paletteItems } from "@/lib/palette";
import { FOCUSABLE_CHROME } from "@/lib/a11y";
import { navItems } from "@/lib/nav";
import { site } from "@/lib/site";

export function SiteHeader({ hasPosts }: { hasPosts: boolean }) {
  const items = navItems(hasPosts);

  return (
    <header className="sticky top-0 z-40 border-b border-border bg-background/72 backdrop-blur-md">
      <div className="mx-auto flex h-14 w-full max-w-2xl items-center gap-4 px-5 sm:px-6">
        <Link
          href="/"
          className="py-2 font-mono text-xs tracking-tight text-foreground"
        >
          {site.handle.toLowerCase()}
          <span className="text-dim">.com</span>
        </Link>

        <nav
          aria-label={FOCUSABLE_CHROME.primaryNavLabel}
          className="flex items-center gap-4"
        >
          {items.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              // py-2 lifts the tap target past 24px inside the fixed h-14 row.
              className="py-2 font-mono text-xs text-dim transition-colors duration-150 hover:text-foreground"
            >
              {item.label}
            </Link>
          ))}
        </nav>

        <div className="ml-auto flex items-center gap-1.5">
          <CommandPalette items={paletteItems(hasPosts)} />
          <ThemeToggle />
        </div>
      </div>
    </header>
  );
}

## VERDICT

**23/100.** Ours copies Geist, thin rules, pills, and activity-grid vocabulary; it misses Chan Dai’s actual frame system. Biggest failure: no bounded `md:max-w-3xl` rail scaffold, so every other cue floats as generic UI. Evidence: [dai-2.css](/tmp/critique/dai-2.css), [ours-live.html](/tmp/critique/ours-live.html), [Chan Dai `globals.css`](https://raw.githubusercontent.com/ncdai/chanhdai.com/main/src/styles/globals.css).

## THE 5 THINGS THAT MOST MAKE OURS LOOK FAKE

1. **Missing rail/grid scaffold**

   - **Chan Dai:** outer `max-w-screen overflow-x-clip px-2`; inner `mx-auto md:max-w-3xl`; `border-x border-line`; `screen-line-top/bottom` pseudo-rules spanning `left:-100vw; width:200vw; height:1px`.
   - **Ours:** `<main>` is `max-w-2xl px-5 sm:px-6`; no vertical rails, no viewport-spanning rules, no margin pattern.
   - **Consequence:** page reads like centered Tailwind content, not Chan Dai’s bounded instrument panel.
   - **Fix:** [app/layout.tsx](/Users/dhruv2mars/dev/github/portfolio/app/layout.tsx:102) → outer `max-w-screen overflow-x-clip px-2`; wrap content in `mx-auto md:max-w-3xl border-x border-line`; add exact `screen-line-*` utilities in [app/globals.css](/Users/dhruv2mars/dev/github/portfolio/app/globals.css:90).

2. **Wrong section grammar**

   - **Chan Dai:** every section is `Panel`: `screen-line-top screen-line-bottom border-x border-line`; header `screen-line-bottom px-4`; title `font-heading text-3xl font-medium tracking-tight text-balance`.
   - **Ours:** `section-label` = mono `12px`, uppercase, `letter-spacing:.09em`; separate `.rule` at `margin-top:12px`.
   - **Consequence:** ours resembles a generic dashboard label, not Chan Dai’s editorial panel architecture.
   - **Fix:** [components/section-heading.tsx](/Users/dhruv2mars/dev/github/portfolio/components/section-heading.tsx:1) → replace label/rule with `PanelHeader`/`PanelTitle`; wrap activity/work in bordered panels.

3. **Typography is numerically wrong**

   - **Chan Dai:** body `16px/1.5`; panel titles `30px/1.2`, weight `500`, tracking `-.025em`; hero name `32px/1`, weight `500`; descriptions `15px/1.6`; nav `14px`, weight `500`, tracking `.025em`; loads Geist Sans, Geist Mono, IBM Plex Serif, Caveat.
   - **Ours:** body `15px/1.72`; hero name `17px/1.4`; section labels `12px/.09em`; descriptions `13px/1.6`; no Caveat/IBM Plex Serif.
   - **Consequence:** hierarchy collapses. Ours feels small, airy, and timid.
   - **Fix:** [app/globals.css](/Users/dhruv2mars/dev/github/portfolio/app/globals.css:70) → use Chan Dai scale; [app/layout.tsx](/Users/dhruv2mars/dev/github/portfolio/app/layout.tsx:1) → load IBM Plex Serif/Caveat variables; [components/masthead.tsx](/Users/dhruv2mars/dev/github/portfolio/components/masthead.tsx:51) → `text-[2rem]/none`.

4. **Color model is wrong, not merely different**

   - **Chan Dai:** neutral zinc system: light `--background:oklch(1 0 0)`, dark `oklch(.141 .005 285.823)`, dark `--border:oklch(.274 .006 286.033)`, neutral `--accent`; blue only for `--link`/`--info`.
   - **Ours:** blue primary accent and blue heatmap; dark background `oklch(.1615 .004 265)`; semantic `--muted` is text gray rather than Chan Dai’s muted surface.
   - **Consequence:** ours looks like a bespoke blue developer template, not the monochrome zinc system.
   - **Fix:** [app/globals.css](/Users/dhruv2mars/dev/github/portfolio/app/globals.css:11) → port reference tokens exactly, including `--line`, `--primary`, `--secondary`, `--card`, `--popover`, `--ring`, `--surface`, `--link`.

5. **Signature components replaced with cheap approximations**

   - **Chan Dai:** geometric logo SVG `h-8`; 120–160px layered avatar; icon-only social buttons `size-8`; `IconTile size-6` with border + ring; dashed row spine; external-link hit area `size-6 after:-inset-2`; theme button `size-8`.
   - **Ours:** text `dhruv2mars.com`; 56–64px dotted placeholder avatar; pill social links with generic arrow; no icon tiles; rounded row hover blocks; 28px theme button.
   - **Consequence:** visual language becomes “developer starter kit” instead of observed reference.
   - **Fix:** [components/site-header.tsx](/Users/dhruv2mars/dev/github/portfolio/components/site-header.tsx:13), [components/masthead.tsx](/Users/dhruv2mars/dev/github/portfolio/components/masthead.tsx:37), [components/projects-section.tsx](/Users/dhruv2mars/dev/github/portfolio/components/projects-section.tsx:14), [components/theme-toggle.tsx](/Users/dhruv2mars/dev/github/portfolio/components/theme-toggle.tsx:35).

## FULL GAP TABLE

| Axis | Chan Dai (actual value) | Ours (actual value) | Severity | Fix |
|---|---|---|---|---|
| Outer layout | `max-w-screen overflow-x-clip px-2` | `max-w-2xl px-5 sm:px-6` | Critical | Change [layout.tsx](/Users/dhruv2mars/dev/github/portfolio/app/layout.tsx:102) |
| Content max width | `md:max-w-3xl` = `48rem` | `max-w-2xl` = `42rem` | Critical | Use `md:max-w-3xl` |
| Horizontal rails | `border-x border-line` | None | Critical | Add border rails around inner shell |
| Full-width rules | `left:-100vw; width:200vw; height:1px` | `.rule` only content width | Critical | Add `screen-line-top/bottom` |
| Margin texture | `.stripe-divider` uses repeating `315deg` gradient | None | Critical | Add diagonal stripe divider |
| Stripe size | `height:calc(var(--spacing) * 8)` = `32px`; `background-size:10px 10px` | None | Critical | Add exact utility |
| Internal dashed spine | `border-r border-dashed border-line` at center | None | High | Add to activity/overview-like grids |
| Header shell | `z-50 max-w-screen overflow-x-clip bg-background px-2` | `z-40 border-b bg-background/72 backdrop-blur-md` | High | Match header shell |
| Header inner | `h-(--header-height)` = `56px`; `md:max-w-3xl`; `border-r border-line pr-2` | `h-14 max-w-2xl px-5 sm:px-6` | High | Match exact classes |
| Header logo | Chan Dai mark SVG, `h-8` | Text `dhruv2mars.com`, mono `12px` | High | Add mark component |
| Header nav | Sans `14px`, weight `500`, tracking `.025em`, muted foreground | Mono `12px`, normal weight | High | Use `text-sm font-medium tracking-wide font-sans` |
| Header separators | Vertical `w-px`, `h-5` = `20px`, `mx-2` | None | Medium | Add separators |
| Command button | `h-8`, borderless, `px-1.5`, icon size `16px` | `h-7`, pill, border, text `⌘ K` | High | Use icon button, not pill |
| Theme button | `size-8`, rounded `min(radius-lg,10px)`, ghost hover | `size-7`, rounded-full | Medium | Use `size-8 rounded-[min(var(--radius-lg),10px)]` |
| Panel boundary | `screen-line-top screen-line-bottom border-x border-line` | No panel boundary | Critical | Create `Panel` primitive |
| Panel header | `screen-line-bottom px-4` | Flex row + `.rule mt-3` | Critical | Use bordered header |
| Panel title | `text-3xl font-medium tracking-tight text-balance` | Mono uppercase `text-xs` | Critical | Use 30px sans title |
| Panel title size | `1.875rem` = `30px`; line `1.2` | `0.75rem` = `12px`; line `1.45` | Critical | Replace section-label treatment |
| Panel title copy | Absolute `top-1 ml-1 size-7`, opacity `0` → `1` on hover | Missing | Medium | Add anchor-copy button |
| Corner markers | Source comments show markers intentionally commented out | None | Low | Do not invent; preserve clean rails |
| Body padding | `p-4` = `16px` | Mostly no panel padding | High | Add `PanelContent p-4` |
| Panel grid gap | `gap-x-4` = `16px`; `gap-y-2.5` = `10px` | Not applicable | High | Use exact grid rhythm |
| Section separators | `stripe-divider` = `32px` | `mt-24` = `96px` | Critical | Replace section margins with separators |
| Hero top spacing | Profile grid; figure `p-2`, responsive `sm:p-4` | Masthead `pt-14`/`pt-20` = `56/80px` | High | Build profile grid |
| Hero structure | Two-column `grid-cols-[auto_1fr]`, rows `1fr auto` | Single flex row | High | Rebuild masthead shell |
| Avatar | Layered images; `size-30`=120, `min-[24rem]:size-32`=128, `sm:size-40`=160 | Placeholder `size-14/16`=56/64 | Critical | Use real image/layered avatar |
| Avatar treatment | Four theme/light-state image layers; inset ring | Dot pattern pseudo-element | High | Replace placeholder |
| Hero name | `text-[2rem]/none`, weight `500`, tracking tight | `text-lg` = `17px`, line `1.4` | Critical | Use exact hero scale |
| Hero tagline | Mono `text-sm` = `14px`; `h-12.5` mobile / `h-9` desktop; top border | Mono `text-xs` = `12px`; no bordered sentence panel | High | Add bordered tagline row |
| Handwritten type | Caveat `font-handwritten`, `text-xl/none`, tracking normal | Missing | Medium | Load/use Caveat only for annotations |
| Serif type | IBM Plex Serif loaded and used in testimonial text `font-serif text-base` | Missing | Low | Add font only where content needs serif |
| Body base | `1rem/1.5` | `0.9375rem/1.72` | High | Set base to `16px/1.5` |
