@import "tailwindcss";
@import "shadcn/tailwind.css";
@import "tw-animate-css";

@import "./typeset.css";
@import "./scroll-fade-effect.css";
@import "./style-preview.css";

@plugin "@tailwindcss/typography";

@custom-variant dark (&:where(.dark, .dark *));

@custom-variant supports-timeline-scroll {
  @supports (animation-timeline: scroll()) {
    @slot;
  }
}

@custom-variant retina {
  @media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 2x) {
    @slot;
  }
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-accent: var(--accent);
  --color-accent-muted: var(--accent-muted);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-line: var(--line);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-info: var(--info);
  --color-success: var(--success);
  --color-destructive: var(--destructive);
  --color-link: var(--link);
  --color-surface: var(--surface);
  --color-surface-foreground: var(--surface-foreground);
  --color-code: var(--code);
  --color-code-foreground: var(--code-foreground);
  --color-code-number: var(--code-number);
  --color-code-highlight: var(--code-highlight);
  --color-selection: var(--selection);
  --color-selection-foreground: var(--selection-foreground);

  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);
  --font-serif: var(--font-serif);
  --font-handwritten: var(--font-handwritten);
  --font-heading: var(--font-sans);

  --default-mono-font-feature-settings: "ss11" 1, "zero" 1, "tnum" 1;

  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);

  --color-chart-label: var(--chart-label);
  --color-chart-ring-background: var(--chart-ring-background);
  --color-chart-marker-foreground: var(--chart-marker-foreground);
  --color-chart-marker-border: var(--chart-marker-border);
  --color-chart-marker-background: var(--chart-marker-background);
  --color-chart-tooltip-muted: var(--chart-tooltip-muted);
  --color-chart-tooltip-foreground: var(--chart-tooltip-foreground);
  --color-chart-tooltip-background: var(--chart-tooltip-background);
  --color-chart-grid: var(--chart-grid);
  --color-chart-crosshair: var(--chart-crosshair);
  --chart-line-secondary: var(--chart-line-secondary);
  --chart-line-primary: var(--chart-line-primary);
  --color-chart-foreground-muted: var(--chart-foreground-muted);
  --color-chart-foreground: var(--chart-foreground);
  --color-chart-background: var(--chart-background);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);

  --animate-spin-ccw: spin-ccw
    var(--tw-animation-duration, var(--tw-duration, 6s)) linear infinite;

  @keyframes spin-ccw {
    to {
      rotate: -360deg;
    }
  }
}

@utility link {
  @apply decoration-1 underline-offset-3 hover:underline;
}

@utility link-underline {
  @apply underline decoration-current/30 decoration-1 underline-offset-3 transition-colors hover:decoration-current;
}

@utility screen-line-top {
  @apply relative;
  &:before {
    content: "";
    @apply absolute top-0 left-[-100vw] -z-1 h-px w-[200vw] bg-line;
  }
}

@utility screen-line-bottom {
  @apply relative;
  &:after {
    content: "";
    @apply absolute bottom-0 left-[-100vw] -z-1 h-px w-[200vw] bg-line;
  }
}

@utility screen-dashed-line-top {
  @apply screen-line-top;
  &:before {
    content: "";
    @apply bg-inherit bg-[linear-gradient(to_right,var(--line)_4px,transparent_2px)] bg-size-[6px_1px] bg-repeat-x;
  }
}

@utility screen-dashed-line-bottom {
  @apply screen-line-bottom;
  &:after {
    content: "";
    @apply bg-inherit bg-[linear-gradient(to_right,var(--line)_4px,transparent_2px)] bg-size-[6px_1px] bg-repeat-x;
  }
}

@utility screen-line-top-none {
  @apply before:content-none;
}

@utility screen-line-bottom-none {
  @apply after:content-none;
}

@utility diagonal-stripes {
  @apply [--pattern-foreground:var(--color-line)]/56;
  @apply bg-[repeating-linear-gradient(315deg,var(--pattern-foreground)_0,var(--pattern-foreground)_1px,transparent_0,transparent_50%)] bg-size-[10px_10px];
}

@utility stripe-divider {
  @apply relative h-8;
  &:before {
    content: "";
    @apply absolute left-[-100vw] -z-1 h-full w-[200vw] diagonal-stripes;
  }
}

@utility step {
  counter-increment: step;
  @apply max-md:pl-10;

  &:before {
    content: counter(step);
    @apply absolute inline-flex size-6 items-center justify-center rounded-lg bg-muted text-center indent-0 text-[0.8125rem]/6 font-normal text-foreground max-md:left-0 md:-ml-10;
  }
}

@utility prose-ncdai {
  @apply prose-headings:font-medium prose-headings:tracking-tight prose-headings:text-pretty md:prose-headings:text-balance prose-h2:text-xl prose-h3:text-lg;
  @apply prose-a:font-normal prose-a:wrap-break-word prose-a:text-foreground prose-a:link-underline;
  @apply prose-code:rounded-md prose-code:border prose-code:bg-muted/50 prose-code:px-1 prose-code:py-px prose-code:text-sm prose-code:font-normal prose-code:before:content-none prose-code:after:content-none retina:prose-code:border-[0.5px];
  @apply prose-strong:font-medium;
  @apply prose-hr:border-line;
  @apply prose-blockquote:border-l prose-blockquote:border-line prose-blockquote:font-normal prose-blockquote:text-muted-foreground prose-blockquote:not-italic prose-blockquote:[&_p:first-of-type]:before:content-none prose-blockquote:[&_p:last-of-type]:after:content-none;
  @apply prose-ul:marker:text-xs/none;
}

@utility code-inline {
  @apply rounded-md border bg-muted/50 px-1 py-px font-mono text-sm font-normal whitespace-pre-wrap in-data-table-nowrap:whitespace-nowrap retina:border-[0.5px];
}

@utility prose-no-margin {
  & > :first-child {
    @apply mt-0;
  }

  & > :last-child {
    @apply mb-0;
  }

  :where(p):not(:where([class~="not-prose"], [class~="not-prose"] *)),
  :where([data-rehype-pretty-code-figure]) {
    @apply mt-3 mb-3;
  }
}

@utility extend-touch-target {
  @media (pointer: coarse) {
    @apply relative touch-manipulation after:absolute after:-inset-2;
  }
}

:root {
  /* white */
