1	import type { Metadata, Viewport } from "next";
2	import { GeistSans } from "geist/font/sans";
3	import { GeistMono } from "geist/font/mono";
4	import { Analytics } from "@vercel/analytics/next";
5	import { SpeedInsights } from "@vercel/speed-insights/next";
6	import { ThemeProvider } from "@/components/theme-provider";
7	import { SiteHeader } from "@/components/site-header";
8	import { SiteFooter } from "@/components/site-footer";
9	import { FOCUSABLE_CHROME } from "@/lib/a11y";
10	import { getPublishedPosts } from "@/lib/blog";
11	import { ogImagePath } from "@/lib/discovery";
12	import { serializeJsonLd } from "@/lib/json-ld";
13	import { profileUrls, site } from "@/lib/site";
14	import "./globals.css";
15	
16	export const metadata: Metadata = {
17	  metadataBase: new URL(site.url),
18	  title: {
19	    default: `${site.name} — ${site.tagline}`,
20	    template: `%s · ${site.name}`,
21	  },
22	  description: site.positioning,
23	  openGraph: {
24	    title: site.name,
25	    description: site.positioning,
26	    url: site.url,
27	    siteName: site.name,
28	    type: "website",
29	    images: [{ url: ogImagePath(site.name) }],
30	  },
31	  twitter: {
32	    card: "summary_large_image",
33	    title: site.name,
34	    description: site.positioning,
35	    images: [ogImagePath(site.name)],
36	  },
37	  alternates: {
38	    types: {
39	      "application/rss+xml": site.rssPath,
40	    },
41	  },
42	};
43	
44	export const viewport: Viewport = {
45	  themeColor: [
46	    { media: "(prefers-color-scheme: dark)", color: "#141416" },
47	    { media: "(prefers-color-scheme: light)", color: "#fbfbfa" },
48	  ],
49	};
50	
51	const jsonLd = {
52	  "@context": "https://schema.org",
53	  "@graph": [
54	    {
55	      "@type": "WebSite",
56	      name: site.name,
57	      url: site.url,
58	      description: site.positioning,
59	      author: { "@type": "Person", name: site.name, url: site.url },
60	    },
61	    {
62	      "@type": "Person",
63	      name: site.name,
64	      url: site.url,
65	      jobTitle: site.tagline,
66	      sameAs: profileUrls(),
67	    },
68	  ],
69	};
70	
71	export default function RootLayout({
72	  children,
73	}: {
74	  children: React.ReactNode;
75	}) {
76	  const hasPosts = getPublishedPosts().length > 0;
77	
78	  return (
79	    <html
80	      lang="en"
81	      className={`preload ${GeistSans.variable} ${GeistMono.variable}`}
82	      suppressHydrationWarning
83	    >
84	      <body className="flex min-h-[100dvh] flex-col">
85	        {/* Drop `.preload` after first paint so the stored theme never
86	            animates in from the wrong colour. */}
87	        <script
88	          dangerouslySetInnerHTML={{
89	            __html:
90	              "requestAnimationFrame(function(){requestAnimationFrame(function(){document.documentElement.classList.remove('preload')})})",
91	          }}
92	        />
93	        <script
94	          type="application/ld+json"
95	          dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
96	        />
97	        <ThemeProvider>
98	          <a href={FOCUSABLE_CHROME.skipToContentHref} className="skip-link">
99	            {FOCUSABLE_CHROME.skipToContentLabel}
