1	"use client";
2	
3	import { useId, useMemo, useState } from "react";
4	import type { CSSProperties } from "react";
5	import { formatTokenCount } from "@/lib/ai-activity";
6	import type { ActivityDay } from "@/lib/ai-activity";
7	import { formatActivityDate, type ActivityWeek } from "@/lib/activity-grid";
8	
9	const MOBILE_WEEKS = 27;
10	
11	function cellLabel(day: ActivityDay): string {
12	  const tokens = `${formatTokenCount(day.tokens)} tokens`;
13	  return day.live
14	    ? `${formatActivityDate(day.date)}: ${tokens} so far today`
15	    : `${formatActivityDate(day.date)}: ${tokens}`;
16	}
17	
18	/**
19	 * A single tab stop with arrow-key traversal (listbox pattern), so 365 cells
20	 * never become 365 tab stops. The readout is aria-hidden — the focused
21	 * option already carries the same sentence.
22	 */
23	export function ActivityGrid({ weeks }: { weeks: readonly ActivityWeek[] }) {
24	  const gridId = useId();
25	  const slots = useMemo(() => weeks.flatMap((week) => week.cells), [weeks]);
26	  const lastFilled = useMemo(
27	    () => slots.reduce((last, slot, i) => (slot ? i : last), 0),
28	    [slots],
29	  );
30	  const [active, setActive] = useState<number | null>(null);
31	
32	  function move(delta: number) {
33	    setActive((current) => {
34	      const next = (current ?? lastFilled) + delta;
35	      if (next < 0 || next >= slots.length || !slots[next]) return current;
36	      return next;
37	    });
38	  }
39	
40	  const activeDay = active === null ? null : slots[active];
41	
42	  return (
43	    <div>
44	      <p
45	        aria-hidden
46	        className="mb-2.5 h-4 font-mono text-2xs text-dim tabular-nums"
47	      >
48	        {activeDay ? (
49	          <>
50	            <span className="text-foreground">
51	              {formatTokenCount(activeDay.tokens)}
52	            </span>{" "}
53	            tokens · {formatActivityDate(activeDay.date)}
54	            {activeDay.live ? " · so far today" : ""}
55	          </>
56	        ) : (
57	          "hover or focus a day"
58	        )}
59	      </p>
60	
61	      <div
62	        role="listbox"
63	        tabIndex={0}
64	        aria-label="Daily AI token usage, last 12 months"
65	        aria-activedescendant={
66	          active !== null && slots[active] ? `${gridId}-${active}` : undefined
67	        }
68	        className="activity-grid"
69	        style={
70	          {
71	            "--weeks": weeks.length,
72	            "--weeks-sm": MOBILE_WEEKS,
73	          } as CSSProperties
74	        }
75	        onFocus={() => setActive((current) => current ?? lastFilled)}
76	        onBlur={() => setActive(null)}
77	        onMouseLeave={() => setActive(null)}
78	        onKeyDown={(event) => {
79	          const step =
80	            event.key === "ArrowLeft"
81	              ? -7
