            }
          >
            {week.monthLabel ? (
              <span className="activity-month">{week.monthLabel}</span>
            ) : null}
            {week.cells.map((day, dayIndex) => {
              const index = weekIndex * 7 + dayIndex;
              if (!day) {
                return <div key={index} aria-hidden className="aspect-square" />;
              }
              return (
                <div
                  key={index}
                  id={`${gridId}-${index}`}
                  role="option"
                  aria-selected={index === active}
                  aria-label={cellLabel(day)}
                  data-active={index === active}
                  data-live={day.live ? "true" : undefined}
                  onMouseEnter={() => setActive(index)}
                  className="activity-cell"
                  style={
                    {
                      "--level": `var(--l${day.intensity})`,
                      "--col": weekIndex,
                    } as CSSProperties
                  }
                />
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

import { ActivityGrid } from "@/components/activity-grid";
import { SectionHeading } from "@/components/section-heading";
import { buildActivityWeeks } from "@/lib/activity-grid";
import { formatTokenCount, materializeAiActivity } from "@/lib/ai-activity";
import { getAiActivityPayload } from "@/lib/ai-activity-store";

function updatedLabel(generatedAt: string | null, timeZone: string): string {
  if (!generatedAt) return "";
  const date = new Date(generatedAt);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    timeZone,
  }).format(date);
}

export async function ActivitySection() {
  const { payload, source } = await getAiActivityPayload();
  const activity = materializeAiActivity(payload);
  const weeks = buildActivityWeeks(activity.days);
  const updated = updatedLabel(activity.generatedAt, activity.timezone);
  // Only a feed published through yesterday earns a projected today.
  const projecting = activity.days.at(-1)?.live === true;

  const provenance =
    source === "fallback"
      ? "fixture data — the live feed is unavailable"
      : !updated
        ? ""
        : projecting
          ? `updated ${updated}`
          : `feed stalled — last updated ${updated}`;

  return (
    <section id="activity" className="mt-24 scroll-mt-24">
      <SectionHeading
        label="AI activity"
        aside={source === "fallback" ? "fixture" : undefined}
      />

      <p className="mt-7 font-mono text-2xl tracking-tight text-foreground">
        {formatTokenCount(activity.lifetimeTokens)}
      </p>
      <p className="mt-1.5 max-w-[52ch] text-sm text-muted">
        tokens through coding agents since I started measuring — one cell per
        day
        {projecting
          ? ", today ringed rather than filled because it is still a projection."
          : "."}
      </p>

      <div className="mt-8">
        <ActivityGrid weeks={weeks} />
      </div>

      <div className="mt-3 flex items-center justify-between gap-4 font-mono text-2xs text-dim">
        <span>{provenance}</span>
        <span className="flex items-center gap-1">
          less
          {[0, 1, 2, 3, 4].map((level) => (
            <span
              key={level}
              aria-hidden
              className="size-2 rounded-[2px]"
              style={{ background: `var(--l${level})` }}
            />
          ))}
          more
        </span>
      </div>
    </section>
  );
}

import { describe, expect, test } from "bun:test";
import {
  ACTIVITY_WINDOW_DAYS,
  buildAiActivity,
  dayFractionElapsed,
  fillSparseDailySeries,
  intensityFromTokens,
  materializeAiActivity,
  materializeHistory,
  projectTodayTokens,
  sevenDayMinBaseline,
  withLiveToday,
  type DailyTokens,
} from "./ai-activity";
import { shiftYmd, type AiActivityPayload } from "./ai-activity-payload";

const FIXTURE: readonly DailyTokens[] = [
  { date: "2026-01-01", tokens: 0 },
  { date: "2026-01-02", tokens: 1_200 },
  { date: "2026-01-03", tokens: 8_500 },
  { date: "2026-01-04", tokens: 25_000 },
  { date: "2026-01-05", tokens: 80_000 },
];

describe("AI Activity read model", () => {
  test("maps intensity relative to the densest day in the series", () => {
    const activity = buildAiActivity(FIXTURE);
    expect(activity.days.map((d) => d.intensity)).toEqual([0, 1, 1, 2, 4]);
  });

  test("lifetime summary prefers payload lifetime when provided", () => {
    const activity = buildAiActivity(FIXTURE, { lifetimeTokens: 9_999_999 });
    expect(activity.lifetimeTokens).toBe(9_999_999);
  });

  test("lifetime summary falls back to series sum", () => {
    const activity = buildAiActivity(FIXTURE);
    expect(activity.lifetimeTokens).toBe(1_200 + 8_500 + 25_000 + 80_000);
  });

  test("relative intensity buckets by ratio to max", () => {
    expect(intensityFromTokens(0, 100)).toBe(0);
    expect(intensityFromTokens(25, 100)).toBe(1);
    expect(intensityFromTokens(50, 100)).toBe(2);
    expect(intensityFromTokens(75, 100)).toBe(3);
    expect(intensityFromTokens(100, 100)).toBe(4);
  });

  test("fillSparseDailySeries zero-fills calendar gaps", () => {
    const filled = fillSparseDailySeries(
      [
        { date: "2026-01-01", tokens: 10 },
        { date: "2026-01-03", tokens: 30 },
      ],
      "2026-01-03",
      3,
    );
    expect(filled).toEqual([
      { date: "2026-01-01", tokens: 10 },
      { date: "2026-01-02", tokens: 0 },
      { date: "2026-01-03", tokens: 30 },
    ]);
  });

  test("materializeHistory + withLiveToday appends projected today", () => {
    const payload: AiActivityPayload = {
      version: 1,
      generatedAt: "2026-07-17T00:20:00.000Z",
      timezone: "Asia/Kolkata",
      days: [
        { date: "2026-07-10", tokens: 100 },
        { date: "2026-07-11", tokens: 80 },
        { date: "2026-07-12", tokens: 60 },
        { date: "2026-07-13", tokens: 40 },
        { date: "2026-07-14", tokens: 90 },
        { date: "2026-07-15", tokens: 70 },
        { date: "2026-07-16", tokens: 50 },
      ],
      lifetimeTokens: 490,
    };
    const noon = new Date("2026-07-17T12:00:00+05:30");
    const history = materializeHistory(payload);
    expect(history.days.at(-1)?.date).toBe("2026-07-16");
    expect(history.lifetimeTokens).toBe(490);

    const activity = withLiveToday(history, noon);
    const today = activity.days.at(-1);
    expect(today?.date).toBe("2026-07-17");
    expect(today?.live).toBe(true);
    expect(today?.tokens).toBeGreaterThan(0);
    expect(today?.tokens).toBeLessThanOrEqual(40);
    // Lifetime stays published nightly total (excludes synthetic today).
    expect(activity.lifetimeTokens).toBe(490);
  });

  test("a stale payload is zero-filled up to today, never skipped", () => {
    const payload: AiActivityPayload = {
      version: 1,
      generatedAt: "2026-07-17T00:20:00.000Z",
      timezone: "Asia/Kolkata",
      days: [
        { date: "2026-07-15", tokens: 70 },
        { date: "2026-07-16", tokens: 50 },
      ],
      lifetimeTokens: 120,
    };
    // A month after the last nightly sync.
    const noon = new Date("2026-08-15T12:00:00+05:30");
    const activity = withLiveToday(materializeHistory(payload), noon);

    const dates = activity.days.map((d) => d.date);
    expect(dates.at(-1)).toBe("2026-08-15");
    expect(dates.at(0)).toBe(shiftYmd("2026-08-15", -(dates.length - 1)));
    // Consecutive calendar days, no jump across the outage.
    for (let i = 1; i < dates.length; i += 1) {
      expect(shiftYmd(dates[i - 1]!, 1)).toBe(dates[i]!);
    }
    // The outage reads as silence, not as activity.
    const outage = activity.days.filter(
      (d) => d.date > "2026-07-16" && d.date < "2026-08-15",
    );
    expect(outage.length).toBe(29);
    expect(outage.every((d) => d.tokens === 0 && d.intensity === 0)).toBe(true);
    // A month-old feed cannot project today — that would invent activity.
    expect(activity.days.some((d) => d.live)).toBe(false);
    expect(activity.days.at(-1)?.tokens).toBe(0);
  });

  test("the display window never exceeds one year of cells", () => {
    const payload: AiActivityPayload = {
      version: 1,
      generatedAt: "2026-07-17T00:20:00.000Z",
      timezone: "Asia/Kolkata",
      days: [
        { date: "2024-01-01", tokens: 10 },
        { date: "2026-07-16", tokens: 50 },
      ],
      lifetimeTokens: 60,
    };
    const activity = materializeAiActivity(
      payload,
      new Date("2026-08-15T12:00:00+05:30"),
    );
    expect(activity.days.length).toBeLessThanOrEqual(ACTIVITY_WINDOW_DAYS);
    expect(activity.days.at(-1)?.date).toBe("2026-08-15");
  });

  test("materializeAiActivity can omit live today for SSR", () => {
    const payload: AiActivityPayload = {
      version: 1,
      generatedAt: "2026-07-17T00:20:00.000Z",
      timezone: "Asia/Kolkata",
      days: [{ date: "2026-07-16", tokens: 50 }],
      lifetimeTokens: 50,
    };
    const noon = new Date("2026-07-17T12:00:00+05:30");
    const activity = materializeAiActivity(payload, noon, {
      includeLiveToday: false,
    });
    expect(activity.days.at(-1)?.date).toBe("2026-07-16");
    expect(activity.days.some((d) => d.live)).toBe(false);
    expect(activity.lifetimeTokens).toBe(50);
  });

  test("materialize fills sparse history so weekdays stay aligned", () => {
    const payload: AiActivityPayload = {
      version: 1,
      generatedAt: "2026-07-17T00:20:00.000Z",
      timezone: "Asia/Kolkata",
      days: [
        { date: "2026-07-10", tokens: 10 },
        { date: "2026-07-16", tokens: 20 },
      ],
      lifetimeTokens: 30,
    };
    const activity = materializeAiActivity(payload, new Date(), {
      includeLiveToday: false,
    });
    const window = activity.days.slice(-7);
    expect(window.map((d) => d.date)).toEqual([
      "2026-07-10",
      "2026-07-11",
      "2026-07-12",
      "2026-07-13",
      "2026-07-14",
      "2026-07-15",
      "2026-07-16",
    ]);
    expect(window.map((d) => d.tokens)).toEqual([10, 0, 0, 0, 0, 0, 20]);
  });
});

describe("AI Activity projection helpers", () => {
  test("sevenDayMinBaseline uses the minimum of the last 7 positive days", () => {
    const days = [
      { date: "2026-07-10", tokens: 50 },
      { date: "2026-07-11", tokens: 40 },
      { date: "2026-07-12", tokens: 0 },
      { date: "2026-07-13", tokens: 20 },
      { date: "2026-07-14", tokens: 30 },
      { date: "2026-07-15", tokens: 25 },
      { date: "2026-07-16", tokens: 60 },
    ];
    expect(sevenDayMinBaseline(days, "2026-07-17")).toBe(20);
  });

  test("projectTodayTokens scales the 7-day min by elapsed day fraction", () => {
    const days = [
      { date: "2026-07-10", tokens: 100 },
      { date: "2026-07-11", tokens: 80 },
      { date: "2026-07-12", tokens: 60 },
      { date: "2026-07-13", tokens: 40 },
      { date: "2026-07-14", tokens: 90 },
      { date: "2026-07-15", tokens: 70 },
      { date: "2026-07-16", tokens: 50 },
    ];
    const noon = new Date("2026-07-17T12:00:00+05:30");
    const projection = projectTodayTokens(days, noon, "Asia/Kolkata");
    expect(projection.date).toBe("2026-07-17");
    expect(projection.baseline).toBe(40);
    const fraction = dayFractionElapsed(noon, "Asia/Kolkata");
    expect(projection.tokens).toBe(Math.round(40 * fraction));
  });
});

import {
  AI_ACTIVITY_TIMEZONE,
  calendarDateInTimeZone,
  type AiActivityPayload,
  shiftYmd,
} from "@/lib/ai-activity-payload";

export type DailyTokens = {
  date: string;
  tokens: number;
};

export type Intensity = 0 | 1 | 2 | 3 | 4;

export type ActivityDay = DailyTokens & {
  intensity: Intensity;
  /** Synthetic “live” projection for the current local day. */
  live?: boolean;
};

export type AiActivity = {
  days: ActivityDay[];
  lifetimeTokens: number;
  /** ISO timestamp of the nightly payload, when known. */
  generatedAt: string | null;
  timezone: string;
};

export type AiActivitySource = "blob" | "fallback";

/** GitHub-like 5-level scale relative to the densest day in the series. */
export function intensityFromTokens(
  tokens: number,
  maxTokens: number,
): Intensity {
  if (tokens <= 0 || maxTokens <= 0) return 0;
  const ratio = tokens / maxTokens;
  if (ratio <= 0.25) return 1;
  if (ratio <= 0.5) return 2;
  if (ratio <= 0.75) return 3;
  return 4;
}

/**
 * Expand a sparse daily series into consecutive calendar days (0-filled gaps)
 * ending on `endDate`, keeping at most `windowDays` cells.
 */
export function fillSparseDailySeries(
  days: readonly DailyTokens[],
  endDate: string,
  windowDays = 365,
): DailyTokens[] {
  const byDate = new Map(days.map((d) => [d.date, d.tokens]));
  const startDate = shiftYmd(endDate, -(windowDays - 1));
  const filled: DailyTokens[] = [];
  for (
    let cursor = startDate;
    cursor <= endDate;
    cursor = shiftYmd(cursor, 1)
  ) {
    filled.push({ date: cursor, tokens: byDate.get(cursor) ?? 0 });
  }
  return filled;
}

export function buildAiActivity(
  series: readonly DailyTokens[],
  options?: {
    liveDate?: string;
    generatedAt?: string | null;
    timezone?: string;
    /** Authoritative lifetime from the payload (preferred over series sum). */
    lifetimeTokens?: number;
  },
): AiActivity {
  const max = Math.max(0, ...series.map((d) => d.tokens));
  const liveDate = options?.liveDate;

  const days: ActivityDay[] = series.map((day) => ({
    ...day,
    intensity: intensityFromTokens(day.tokens, max),
    live: liveDate === day.date ? true : undefined,
  }));

  const seriesSum = series.reduce((sum, day) => sum + day.tokens, 0);
  const lifetimeTokens =
    options?.lifetimeTokens !== undefined
      ? options.lifetimeTokens
      : seriesSum;

  return {
    days,
    lifetimeTokens,
    generatedAt: options?.generatedAt ?? null,
    timezone: options?.timezone ?? AI_ACTIVITY_TIMEZONE,
  };
}

/**
 * Fraction of the local calendar day elapsed [0, 1].
 */
export function dayFractionElapsed(now: Date, timeZone: string): number {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hour: "numeric",
    minute: "numeric",
    second: "numeric",
    hourCycle: "h23",
  }).formatToParts(now);
  const hour = Number(parts.find((p) => p.type === "hour")?.value ?? 0);
  const minute = Number(parts.find((p) => p.type === "minute")?.value ?? 0);
  const second = Number(parts.find((p) => p.type === "second")?.value ?? 0);
  const elapsed = hour * 3600 + minute * 60 + second;
  return Math.min(1, Math.max(0, elapsed / 86_400));
}

/**
 * Conservative full-day baseline: minimum of the last up-to-7 days
 * before `beforeDate` that have tokens > 0.
 */
export function sevenDayMinBaseline(
  days: readonly { date: string; tokens: number }[],
  beforeDate: string,
): number {
  const prior = days
    .filter((d) => d.date < beforeDate && d.tokens > 0)
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(-7);
  if (prior.length === 0) return 0;
  return Math.min(...prior.map((d) => d.tokens));
}

/** Projected tokens “so far today” from the 7-day min baseline. */
export function projectTodayTokens(
  days: readonly { date: string; tokens: number }[],
  now: Date,
  timeZone: string,
): { date: string; tokens: number; baseline: number } {
  const today = calendarDateInTimeZone(now, timeZone);
  const baseline = sevenDayMinBaseline(days, today);
  const tokens = Math.round(baseline * dayFractionElapsed(now, timeZone));
  return { date: today, tokens, baseline };
}

/** Cacheable history through the payload’s last published day (no live today). */
export function materializeHistory(payload: AiActivityPayload): AiActivity {
  const timeZone = payload.timezone || AI_ACTIVITY_TIMEZONE;
  const history = [...payload.days].sort((a, b) =>
    a.date.localeCompare(b.date),
  );
  const endHistory = history.at(-1)!.date;

  return buildAiActivity(fillSparseDailySeries(history, endHistory, 364), {
    generatedAt: payload.generatedAt,
    timezone: timeZone,
    lifetimeTokens: payload.lifetimeTokens,
  });
}

/** Window kept for display: one year of consecutive days ending today. */
export const ACTIVITY_WINDOW_DAYS = 365;

/**
 * Extend the history to today. Two rules keep the grid honest:
 *
 * 1. Days between the last published day and today are zero-filled, never
 *    skipped — the series must stay consecutive or every cell lands on the
 *    wrong weekday.
 * 2. Today is projected only when the payload is fresh (published through
 *    yesterday). A stale feed means no data, and no data is drawn as zero,
 *    not as a guess from month-old numbers.
 *
 * Lifetime stays the published nightly total (excludes synthetic today).
 */
export function withLiveToday(history: AiActivity, now = new Date()): AiActivity {
  const timeZone = history.timezone;
  const today = calendarDateInTimeZone(now, timeZone);
  const lastPublished = history.days.at(-1)?.date ?? "";
  // Avoid duplicating the last published day if clocks briefly disagree.
  if (!lastPublished || today <= lastPublished) return history;

  const fresh = shiftYmd(today, -1) <= lastPublished;
  const max = Math.max(0, ...history.days.map((d) => d.tokens));

  const appended: ActivityDay[] = [];
  for (
    let cursor = shiftYmd(lastPublished, 1);
    cursor <= today;
    cursor = shiftYmd(cursor, 1)
  ) {
    if (cursor === today && fresh) {
      const projection = projectTodayTokens(history.days, now, timeZone);
      appended.push({
        date: today,
        tokens: projection.tokens,
        intensity: intensityFromTokens(projection.tokens, max),
        live: true,
      });
    } else {
      appended.push({ date: cursor, tokens: 0, intensity: 0 });
    }
  }

  return {
    days: [...history.days, ...appended].slice(-ACTIVITY_WINDOW_DAYS),
    lifetimeTokens: history.lifetimeTokens,
    generatedAt: history.generatedAt,
    timezone: history.timezone,
  };
}

export function materializeAiActivity(
  payload: AiActivityPayload,
  now = new Date(),
  options?: { includeLiveToday?: boolean },
): AiActivity {
  const history = materializeHistory(payload);
  if (options?.includeLiveToday === false) return history;
  return withLiveToday(history, now);
}

export function formatTokenCount(tokens: number): string {
  return new Intl.NumberFormat("en-US").format(tokens);
}

export const LIVE_COUNT_START_RATIO = 0.8;
export const LIVE_COUNT_DURATION_MS = 90_000;

