(async () => {
  const cv = document.createElement('canvas'); cv.width = cv.height = 1;
  const ctx = cv.getContext('2d');
  const px = (s) => { ctx.clearRect(0,0,1,1); ctx.fillStyle = '#000'; ctx.fillStyle = s; ctx.fillRect(0,0,1,1); return [...ctx.getImageData(0,0,1,1).data].slice(0,3); };
  const lum = (c) => { const [r,g,b] = c.map(v => { v/=255; return v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4); }); return 0.2126*r + 0.7152*g + 0.0722*b; };
  const measure = () => {
    const cs = getComputedStyle(document.documentElement);
    const bg = lum(px(cs.getPropertyValue('--background')));
    const r = (t) => { const [x,y] = [lum(px(cs.getPropertyValue(t))), bg].sort((p,q)=>q-p); return +((x+0.05)/(y+0.05)).toFixed(2); };
    return { theme: document.documentElement.classList.contains('dark') ? 'dark' : 'light', fg: r('--foreground'), muted: r('--muted'), dim: r('--dim'), accent: r('--accent') };
  };
  const a = measure();
  document.querySelector('header button[aria-label*="theme"]').click();
  await new Promise(r => setTimeout(r, 700));
  const b = measure();
  return [a, b];
})()

