--------------------------------------------------------------------------- */

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 50%;
  z-index: 90;
  translate: -50% -300%;
  padding: 0.5rem 0.875rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--background);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  transition: translate 200ms var(--ease-out-quint);
}
.skip-link:focus-visible {
  translate: -50% 0;
}

/* ---------------------------------------------------------------------------
