  line-height: 1.3;
  margin-top: 2.5em;
}
.prose h3 {
  font-size: 1.25rem;
  line-height: 1.35;
  margin-top: 2em;
}
.prose h2 + *,
.prose h3 + * {
  margin-top: 0.75em;
