  border-left: 2px solid var(--border);
  color: var(--muted-foreground);
  font-style: italic;
}
.prose hr {
  border: 0;
  border-top: 1px solid var(--line);
}
.prose img {
  border: 1px solid var(--line);
}
.prose :not(pre) > code {
  font-family: var(--font-mono);
  font-size: 0.85em;
  background: var(--muted);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 0.1em 0.35em;
}
.prose pre {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  line-height: 1.6;
  background: var(--code);
  color: var(--code-foreground);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 1rem 1.125rem;
  overflow-x: auto;
}
.prose pre code {
  background: none;
  border: 0;
  padding: 0;
}
.prose .anchor {
  position: absolute;
}

/* sugar-high — four roles, no rainbow */
