import { ActivityGrid } from "@/components/activity-grid";
import { SectionHeading } from "@/components/section-heading";
import { buildActivityWeeks } from "@/lib/activity-grid";
import { formatTokenCount, materializeAiActivity } from "@/lib/ai-activity";
import { getAiActivityPayload } from "@/lib/ai-activity-store";

function updatedLabel(generatedAt: string | null, timeZone: string): string {
  if (!generatedAt) return "";
  const date = new Date(generatedAt);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    timeZone,
  }).format(date);
}

export async function ActivitySection() {
  const { payload, source } = await getAiActivityPayload();
  const activity = materializeAiActivity(payload);
  const weeks = buildActivityWeeks(activity.days);
  const updated = updatedLabel(activity.generatedAt, activity.timezone);
  // Only a feed published through yesterday earns a projected today.
  const projecting = activity.days.at(-1)?.live === true;

  const provenance =
    source === "fallback"
      ? "fixture data — the live feed is unavailable"
      : !updated
        ? ""
        : projecting
          ? `updated ${updated}`
          : `feed stalled — last updated ${updated}`;

  return (
    <section id="activity" className="mt-24 scroll-mt-24">
      <SectionHeading
        label="AI activity"
        aside={source === "fallback" ? "fixture" : undefined}
      />

      <p className="mt-7 font-mono text-2xl tracking-tight text-foreground">
        {formatTokenCount(activity.lifetimeTokens)}
      </p>
      <p className="mt-1.5 max-w-[52ch] text-sm text-muted">
        tokens through coding agents since I started measuring — one cell per
        day
        {projecting
          ? ", today ringed rather than filled because it is still a projection."
          : "."}
      </p>

      <div className="mt-8">
        <ActivityGrid weeks={weeks} />
      </div>

      <div className="mt-3 flex items-center justify-between gap-4 font-mono text-2xs text-dim">
        <span>{provenance}</span>
        <span className="flex items-center gap-1">
          less
          {[0, 1, 2, 3, 4].map((level) => (
            <span
              key={level}
              aria-hidden
              className="size-2 rounded-[2px]"
              style={{ background: `var(--l${level})` }}
            />
          ))}
          more
        </span>
      </div>
    </section>
  );
}

import { ArrowUpRight } from "@/components/icons";
import { SectionHeading } from "@/components/section-heading";
import { destinationHost, getProjects } from "@/lib/projects";
import { site } from "@/lib/site";

export function ProjectsSection() {
  const projects = getProjects();

  return (
    <section id="work" className="mt-24 scroll-mt-24">
      <SectionHeading label="work" aside={`${projects.length} selected`} />

      <ul className="mt-2">
        {projects.map((project) => (
          <li key={project.name} className="border-b border-border last:border-0">
            <a
              href={project.live ?? project.url}
              target="_blank"
              rel="noopener noreferrer"
              className="row-item flex items-baseline gap-4"
            >
              <span className="min-w-0 flex-1">
                <span className="flex flex-wrap items-baseline gap-x-2.5 gap-y-1">
                  <span className="text-base font-medium tracking-tight text-foreground">
                    {project.name}
                  </span>
                  <span className="font-mono text-2xs text-dim">
                    {project.language}
                  </span>
                  {project.note ? (
                    <span className="rounded-full border border-border px-2 py-0.5 font-mono text-2xs text-dim">
                      {project.note}
                    </span>
                  ) : null}
                </span>
                <span className="mt-1.5 block max-w-[52ch] text-sm text-muted">
                  {project.description}
                </span>
              </span>

              <span className="relative shrink-0 font-mono text-2xs text-dim">
                <span className="row-year block tabular-nums">{project.year}</span>
                <span className="row-dest absolute right-0 top-0 flex items-center gap-1 whitespace-nowrap">
                  {destinationHost(project)}
                  <ArrowUpRight className="size-3" />
                </span>
              </span>
            </a>
          </li>
        ))}
      </ul>

      <p className="mt-6 font-mono text-2xs text-dim">
        <a
          href={`https://github.com/${site.handle}?tab=repositories`}
          target="_blank"
          rel="noopener noreferrer"
          className="link-quiet inline-flex min-h-6 items-center"
        >
          everything else on GitHub
        </a>
      </p>
    </section>
  );
}

