import { ActivityGrid, LEVEL_ALPHA } from "@/components/activity-grid";
import {
  Panel,
  PanelDescription,
  PanelHeader,
  PanelTitle,
  PanelTitleSup,
} from "@/components/panel";
import { Tag } from "@/components/tag";
import { buildActivityWeeks } from "@/lib/activity-grid";
import { formatTokenCount, materializeAiActivity } from "@/lib/ai-activity";
import { getAiActivityPayload } from "@/lib/ai-activity-store";

function updatedLabel(generatedAt: string | null, timeZone: string): string {
  if (!generatedAt) return "";
  const date = new Date(generatedAt);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    timeZone,
  }).format(date);
}

export async function ActivitySection() {
  const { payload, source } = await getAiActivityPayload();
  const activity = materializeAiActivity(payload);
  const weeks = buildActivityWeeks(activity.days);
  const updated = updatedLabel(activity.generatedAt, activity.timezone);
  // Only a feed published through yesterday earns a projected today.
  const projecting = activity.days.at(-1)?.live === true;

  const provenance =
    source === "fallback"
      ? "fixture data — the live feed is unavailable"
      : !updated
        ? ""
        : projecting
          ? `updated ${updated}`
          : `feed stalled — last updated ${updated}`;

  return (
    <Panel id="activity">
      <PanelHeader>
        <PanelTitle>
          AI activity
          <PanelTitleSup>{formatTokenCount(activity.lifetimeTokens)}</PanelTitleSup>
        </PanelTitle>
        <PanelDescription>
          Tokens through coding agents since I started measuring — one cell per
          day
          {projecting
            ? ", today ringed rather than filled because it is still a projection."
            : "."}
        </PanelDescription>
      </PanelHeader>

      <figure>
        <div className="py-4">
          <ActivityGrid weeks={weeks} />
        </div>

        <figcaption className="flex items-center justify-between gap-4 border-t border-line px-4 py-3 text-sm text-muted-foreground">
          <span className="flex items-center gap-2">
            <span className="tracking-wide text-muted-foreground/80">
              Fig. 2.
            </span>
            {source === "fallback" ? <Tag>fixture</Tag> : null}
            <span>{provenance}</span>
          </span>
          <span className="flex shrink-0 items-center gap-1 font-mono text-xs">
            less
            {LEVEL_ALPHA.map((alpha) => (
              <span
                key={alpha}
                aria-hidden
                className="size-2.5"
                style={{
                  background: `color-mix(in oklab, var(--muted-foreground) ${alpha}, transparent)`,
                }}
              />
            ))}
            more
          </span>
        </figcaption>
      </figure>
    </Panel>
  );
}

"use client";

import { useId, useMemo, useState } from "react";
import type { CSSProperties } from "react";
import { formatTokenCount } from "@/lib/ai-activity";
import type { ActivityDay } from "@/lib/ai-activity";
import { formatActivityDate, type ActivityWeek } from "@/lib/activity-grid";

const MOBILE_WEEKS = 27;

/** Five steps of the neutral foreground. Intensity is opacity, never hue. */
export const LEVEL_ALPHA = ["10%", "20%", "40%", "60%", "80%"] as const;

function cellLabel(day: ActivityDay): string {
  const tokens = `${formatTokenCount(day.tokens)} tokens`;
  return day.live
    ? `${formatActivityDate(day.date)}: ${tokens} so far today`
    : `${formatActivityDate(day.date)}: ${tokens}`;
}

/**
 * A single tab stop with arrow-key traversal (listbox pattern), so 365 cells
 * never become 365 tab stops. The readout is aria-hidden — the focused
 * option already carries the same sentence.
 */
export function ActivityGrid({ weeks }: { weeks: readonly ActivityWeek[] }) {
  const gridId = useId();
  const slots = useMemo(() => weeks.flatMap((week) => week.cells), [weeks]);
  const lastFilled = useMemo(
    () => slots.reduce((last, slot, i) => (slot ? i : last), 0),
    [slots],
  );
  const [active, setActive] = useState<number | null>(null);

  function move(delta: number) {
    setActive((current) => {
      const next = (current ?? lastFilled) + delta;
      if (next < 0 || next >= slots.length || !slots[next]) return current;
      return next;
    });
  }

  const activeDay = active === null ? null : slots[active];

  return (
    <div className="overflow-x-auto">
      <p
        aria-hidden
        className="mb-2.5 h-4 px-4 font-mono text-xs text-muted-foreground tabular-nums"
      >
        {activeDay ? (
          <>
            <span className="text-foreground">
              {formatTokenCount(activeDay.tokens)}
            </span>{" "}
            tokens · {formatActivityDate(activeDay.date)}
            {activeDay.live ? " · so far today" : ""}
          </>
        ) : (
          "hover or focus a day"
        )}
      </p>

      <div
        role="listbox"
        tabIndex={0}
        aria-label="Daily AI token usage, last 12 months"
        aria-activedescendant={
          active !== null && slots[active] ? `${gridId}-${active}` : undefined
        }
        className="activity-grid"
        style={
          {
            "--weeks": weeks.length,
            "--weeks-sm": MOBILE_WEEKS,
          } as CSSProperties
        }
        onFocus={() => setActive((current) => current ?? lastFilled)}
        onBlur={() => setActive(null)}
        onMouseLeave={() => setActive(null)}
        onKeyDown={(event) => {
          const step =
            event.key === "ArrowLeft"
              ? -7
              : event.key === "ArrowRight"
                ? 7
                : event.key === "ArrowUp"
                  ? -1
                  : event.key === "ArrowDown"
                    ? 1
                    : 0;
          if (step === 0) return;
          event.preventDefault();
          move(step);
        }}
      >
        {weeks.map((week, weekIndex) => (
          <div
            key={week.key}
            className="activity-col"
            // Derived, not a fixed nth-child: a 365-day window is 53 or 54
            // columns, and the narrow grid must show exactly MOBILE_WEEKS.
            data-narrow-hidden={
              weekIndex < weeks.length - MOBILE_WEEKS ? "true" : undefined
            }
          >
            {week.monthLabel ? (
              <span className="activity-month">{week.monthLabel}</span>
            ) : null}
            {week.cells.map((day, dayIndex) => {
              const index = weekIndex * 7 + dayIndex;
              if (!day) {
                return <div key={index} aria-hidden />;
              }
              return (
                <div
                  key={index}
                  id={`${gridId}-${index}`}
                  role="option"
                  aria-selected={index === active}
                  aria-label={cellLabel(day)}
                  data-active={index === active}
                  data-live={day.live ? "true" : undefined}
                  onMouseEnter={() => setActive(index)}
                  className="activity-cell"
                  style={
                    {
                      "--level": LEVEL_ALPHA[day.intensity] ?? LEVEL_ALPHA[0],
                      "--col": weekIndex,
                    } as CSSProperties
                  }
                />
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

import { Panel, PanelContent } from "@/components/panel";
import { SOCIAL_ICONS } from "@/components/icons";
import { site } from "@/lib/site";

/** One line of context. Proof lives in the panels below it, not in it. */
export function Overview() {
  return (
    <Panel>
      <PanelContent>
        <p className="typeset typeset-description text-muted-foreground">
          {site.positioning}
        </p>
      </PanelContent>
    </Panel>
  );
}

export function SocialLinks() {
  return (
    <Panel>
      <PanelContent className="flex flex-wrap gap-2">
        {site.socials.map((social) => {
          const Glyph = SOCIAL_ICONS[social.label];
          const isMail = social.href.startsWith("mailto:");
          return (
            <a
              key={social.label}
              href={social.href}
              target={isMail ? undefined : "_blank"}
              rel="noopener noreferrer"
              aria-label={social.label}
              title={social.label}
              className="flex size-8 items-center justify-center rounded-md border border-line text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground"
            >
              <Glyph className="size-4.5" />
            </a>
          );
        })}
      </PanelContent>
    </Panel>
  );
}

import Image from "next/image";
import { SiteMarkIsometric } from "@/components/site-mark";
import { site } from "@/lib/site";

/** "Dhruv Sharma" → "DS". */
function initials(name: string): string {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? "")
    .join("");
}

function Avatar() {
  return (
    <div className="relative m-0.5 size-16 overflow-hidden rounded-lg border border-line bg-muted ring-1 ring-border/50 select-none">
      {site.avatar ? (
        <Image
          src={site.avatar}
          alt={site.name}
          fill
          sizes="64px"
          priority
          className="object-cover"
        />
      ) : (
        <span className="absolute inset-0 flex items-center justify-center font-heading text-xl font-medium tracking-tight text-foreground">
          {initials(site.name)}
        </span>
      )}
    </div>
  );
}

/**
 * The hero is a four-cell frame rather than a stacked block: the mark occupies
 * a plate captioned like a figure, the avatar sits in its own gutter column,
 * and the name and role stack against the bottom edge so all three meet on one
 * baseline. Nothing here is centred.
 */
export function ProfileHeader() {
  return (
    <div className="screen-line-bottom grid grid-cols-[auto_1fr] grid-rows-[1fr_auto] overflow-y-clip border-x border-line">
      <figure className="relative col-span-2 p-2 sm:col-span-1 sm:col-start-2 sm:p-4">
        <SiteMarkIsometric className="mx-auto h-28 sm:h-32" />
        <figcaption className="pointer-events-none absolute right-2 bottom-2 text-sm leading-none tracking-wide text-[color-mix(in_oklab,var(--muted-foreground)_60%,var(--background))] tabular-nums select-none sm:right-4 sm:bottom-4">
          Fig. 1.
        </figcaption>
      </figure>

      <div className="flex flex-col sm:row-span-2 sm:row-start-1">
        <div className="screen-line-top mt-auto shrink-0 border-r border-line">
          <Avatar />
        </div>
      </div>

      <div className="flex flex-col">
        <div className="z-1 mt-auto border-t border-line">
          <div className="flex items-center gap-2 pl-4">
            <h1 className="-translate-y-px text-[2rem]/none font-medium tracking-tight">
              {site.name}
            </h1>
          </div>
          <p className="flex h-12.5 items-center border-t border-line py-1 pl-4 text-muted-foreground sm:h-9">
            {site.tagline}
          </p>
        </div>
      </div>
    </div>
  );
}

export type Project = {
  name: string;
  description: string;
  url: string;
  /** Live demo or docs, when one exists and is different from `url`. */
  live?: string;
  language: string;
  year: number;
  /** Short third-party signal. Only ever a fact, never a vanity metric. */
  note?: string;
};

/**
 * Curated, not enumerated. The GitHub account has ~45 repos; eight earn a
 * row here. Order is editorial: the agentic thesis first, then shipped
 * craft. See CONTEXT.md → Project.
 */
const PROJECTS: readonly Project[] = [
  {
    name: "relunar",
    description:
      "CLI-first repro harness for coding agents — deterministic sandboxes, issue reads, and reports.",
