        </figcaption>
      </figure>
    </Panel>
  );
}

"use client";

import { useId, useMemo, useState } from "react";
import type { CSSProperties } from "react";
import { formatTokenCount } from "@/lib/ai-activity";
import type { ActivityDay } from "@/lib/ai-activity";
import {
  formatActivityDate,
  LEVEL_ALPHA,
  type ActivityWeek,
} from "@/lib/activity-grid";

const MOBILE_WEEKS = 27;

function cellLabel(day: ActivityDay): string {
  const tokens = `${formatTokenCount(day.tokens)} tokens`;
  return day.live
    ? `${formatActivityDate(day.date)}: ${tokens} so far today`
    : `${formatActivityDate(day.date)}: ${tokens}`;
}

/**
 * A single tab stop with arrow-key traversal (listbox pattern), so 365 cells
 * never become 365 tab stops. The readout is aria-hidden — the focused
 * option already carries the same sentence.
 */
export function ActivityGrid({ weeks }: { weeks: readonly ActivityWeek[] }) {
  const gridId = useId();
  const slots = useMemo(() => weeks.flatMap((week) => week.cells), [weeks]);
  const lastFilled = useMemo(
    () => slots.reduce((last, slot, i) => (slot ? i : last), 0),
    [slots],
  );
  const [active, setActive] = useState<number | null>(null);

  function move(delta: number) {
    setActive((current) => {
      const next = (current ?? lastFilled) + delta;
      if (next < 0 || next >= slots.length || !slots[next]) return current;
      return next;
    });
  }

  const activeDay = active === null ? null : slots[active];

  return (
    <div className="overflow-x-auto">
      <p
        aria-hidden
        className="mb-2.5 h-4 px-4 font-mono text-xs text-muted-foreground tabular-nums"
      >
        {activeDay ? (
          <>
            <span className="text-foreground">
              {formatTokenCount(activeDay.tokens)}
            </span>{" "}
            tokens · {formatActivityDate(activeDay.date)}
            {activeDay.live ? " · so far today" : ""}
          </>
        ) : (
          "hover or focus a day"
        )}
      </p>

      <div
        role="listbox"
        tabIndex={0}
        aria-label="Daily AI token usage, last 12 months"
        aria-activedescendant={
          active !== null && slots[active] ? `${gridId}-${active}` : undefined
        }
        className="activity-grid"
        style={
          {
            "--weeks": weeks.length,
            "--weeks-sm": MOBILE_WEEKS,
          } as CSSProperties
        }
        onFocus={() => setActive((current) => current ?? lastFilled)}
        onBlur={() => setActive(null)}
        onMouseLeave={() => setActive(null)}
        onKeyDown={(event) => {
          const step =
            event.key === "ArrowLeft"
              ? -7
              : event.key === "ArrowRight"
                ? 7
                : event.key === "ArrowUp"
                  ? -1
                  : event.key === "ArrowDown"
                    ? 1
                    : 0;
          if (step === 0) return;
          event.preventDefault();
          move(step);
        }}
      >
        {weeks.map((week, weekIndex) => (
          <div
            key={week.key}
            className="activity-col"
            // Derived, not a fixed nth-child: a 365-day window is 53 or 54
            // columns, and the narrow grid must show exactly MOBILE_WEEKS.
            data-narrow-hidden={
              weekIndex < weeks.length - MOBILE_WEEKS ? "true" : undefined
            }
          >
            {week.monthLabel ? (
              <span className="activity-month">{week.monthLabel}</span>
            ) : null}
            {week.cells.map((day, dayIndex) => {
              const index = weekIndex * 7 + dayIndex;
              if (!day) {
                return <div key={index} aria-hidden />;
              }
              return (
                <div
                  key={index}
                  id={`${gridId}-${index}`}
                  role="option"
                  aria-selected={index === active}
                  aria-label={cellLabel(day)}
                  data-active={index === active}
                  data-live={day.live ? "true" : undefined}
                  onMouseEnter={() => setActive(index)}
                  className="activity-cell"
                  style={
                    {
                      "--level": LEVEL_ALPHA[day.intensity] ?? LEVEL_ALPHA[0],
                      "--col": weekIndex,
                    } as CSSProperties
                  }
                />
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

import type { ActivityDay } from "@/lib/ai-activity";

/**
 * Five steps of the neutral foreground. Intensity is opacity, never hue.
 * Lives here rather than in the grid component because the server-rendered
 * legend reads it too, and a `"use client"` module's exports are client
 * references on the server, not values.
 */
export const LEVEL_ALPHA = ["10%", "20%", "40%", "60%", "80%"] as const;

export type ActivityWeek = {
  /** ISO date of the week's Sunday-aligned first slot. */
  key: string;
  /** Present only on the week that opens a new month. */
  monthLabel?: string;
  /** Sunday → Saturday. `null` pads the partial first and last weeks. */
  cells: (ActivityDay | null)[];
};

/** Day of week (0 = Sunday) for a YYYY-MM-DD calendar date. */
export function weekdayIndex(date: string): number {
  const [y, m, d] = date.split("-").map(Number);
  return new Date(Date.UTC(y!, m! - 1, d!, 12)).getUTCDay();
}

export function monthAbbreviation(date: string): string {
  const [y, m, d] = date.split("-").map(Number);
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(y!, m! - 1, d!, 12)));
}

/** Long, human date for readouts and cell labels: "Sat, Aug 3, 2026". */
export function formatActivityDate(date: string): string {
  const [y, m, d] = date.split("-").map(Number);
  return new Intl.DateTimeFormat("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(y!, m! - 1, d!, 12)));
}

/**
 * Chunk a consecutive day series into Sunday-aligned weeks, padding the
 * partial weeks at both ends so every column is exactly seven slots tall.
 * A month label is attached to the first week that opens a new month, and
 * never to the final week (there is no room to render it).
 */
export function buildActivityWeeks(
  days: readonly ActivityDay[],
): ActivityWeek[] {
  if (days.length === 0) return [];

  const weeks: ActivityWeek[] = [];
  let cells: (ActivityDay | null)[] = new Array(weekdayIndex(days[0]!.date)).fill(
    null,
  );

  for (const day of days) {
    cells.push(day);
    if (cells.length === 7) {
      weeks.push({ key: cells.find(Boolean)!.date, cells });
      cells = [];
    }
  }
  if (cells.length > 0) {
    weeks.push({
      key: cells.find(Boolean)!.date,
      cells: [...cells, ...new Array(7 - cells.length).fill(null)],
    });
  }

  let labelled = "";
  weeks.forEach((week, index) => {
    // The last column has no horizontal room for a label.
    if (index === weeks.length - 1) return;
    const first = week.cells.find(Boolean);
    if (!first) return;
    const month = first.date.slice(0, 7);
    if (month === labelled) return;
    labelled = month;
    // Skip a label that would collide with the previous one on a stub week.
    if (index === 0 && week.cells[0] === null) return;
    week.monthLabel = monthAbbreviation(first.date);
  });

  return weeks;
}

export type SocialLink = {
  label: "X" | "GitHub" | "LinkedIn" | "Email";
  href: string;
};

export const site = {
  name: "Dhruv Sharma",
  handle: "Dhruv2mars",
  /** The positioning, shown under the name. Lowercase on purpose. */
  tagline: "agentic engineer",
  /** One line of context. Proof lives below it, not in it. */
  positioning:
    "I build tooling for coding agents — repro harnesses, queues, local-first inference — and ship with them every day.",
  url: "https://dhruv2mars.com",
  /**
   * No portrait exists yet. The profile header reserves this slot and renders
   * a monogram at the same size; setting this to an image path is the only
   * change needed to fill it, with no layout shift.
   */
  avatar: null as string | null,
  socials: [
    { label: "X", href: "https://x.com/Dhruv2mars" },
    { label: "GitHub", href: "https://github.com/Dhruv2mars" },
    { label: "LinkedIn", href: "https://linkedin.com/in/dhruv2mars" },
    { label: "Email", href: "mailto:Dhruv2mars@gmail.com" },
  ] as const satisfies readonly SocialLink[],
  rssPath: "/feed.xml",
} as const;

/** Socials minus mailto, for `sameAs` in structured data. */
export function profileUrls(): string[] {
  return site.socials
    .filter((s) => !s.href.startsWith("mailto:"))
    .map((s) => s.href);
}

import Image from "next/image";
import { SiteMarkIsometric } from "@/components/site-mark";
import { site } from "@/lib/site";

/** "Dhruv Sharma" → "DS". */
function initials(name: string): string {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? "")
    .join("");
}

function Avatar() {
  return (
    <div className="relative m-0.5 size-16 overflow-hidden rounded-lg border border-line bg-muted ring-1 ring-border/50 select-none">
      {site.avatar ? (
        <Image
          src={site.avatar}
          alt={site.name}
          fill
          sizes="64px"
          priority
          className="object-cover"
        />
      ) : (
        <span className="absolute inset-0 flex items-center justify-center font-heading text-xl font-medium tracking-tight text-foreground">
          {initials(site.name)}
        </span>
      )}
    </div>
  );
}

/**
 * The hero is a four-cell frame rather than a stacked block: the mark occupies
 * a plate captioned like a figure, the avatar sits in its own gutter column,
 * and the name and role stack against the bottom edge so all three meet on one
 * baseline. Nothing here is centred.
 */
export function ProfileHeader() {
  return (
    <div className="screen-line-bottom grid grid-cols-[auto_1fr] grid-rows-[1fr_auto] overflow-y-clip border-x border-line">
      <figure className="relative col-span-2 p-2 sm:col-span-1 sm:col-start-2 sm:p-4">
        <SiteMarkIsometric className="mx-auto h-28 sm:h-32" />
        <figcaption className="pointer-events-none absolute right-2 bottom-2 text-sm leading-none tracking-wide text-[color-mix(in_oklab,var(--muted-foreground)_60%,var(--background))] tabular-nums select-none sm:right-4 sm:bottom-4">
          Fig. 1.
        </figcaption>
      </figure>

      <div className="flex flex-col sm:row-span-2 sm:row-start-1">
        <div className="screen-line-top mt-auto shrink-0 border-r border-line">
          <Avatar />
        </div>
      </div>

      <div className="flex flex-col">
        <div className="z-1 mt-auto border-t border-line">
          <div className="flex items-baseline gap-2 pl-4">
            <h1 className="-translate-y-px text-[2rem]/none font-medium tracking-tight">
              {site.name}
            </h1>
            {/* A margin note, in the hand it would be written in: the monogram
                is a placeholder and says so. It disappears the moment
                `site.avatar` is set. */}
            {site.avatar ? null : (
              <span className="font-handwriting text-lg/none text-muted-foreground/70 select-none max-sm:hidden">
                portrait pending
              </span>
            )}
          </div>
          <p className="flex h-12.5 items-center border-t border-line py-1 pl-4 text-muted-foreground sm:h-9">
            {site.tagline}
          </p>
        </div>
      </div>
    </div>
  );
}

